import argparse
import logging
import logging.handlers
import os
import pickle
import select
import socket
import struct

from six.moves import socketserver

from ta_logcollector.settings import LOG_FORMAT, LOGGER_PORT, SERVER_HOST, LC_LOG_SERVER_ABORT

SERVER_CONTINUE = True


class LogRecordStreamHandler(socketserver.StreamRequestHandler):
    """
    Handler for a streaming logging request.

    This basically logs the record using whatever logging policy is
    configured locally.
    """

    def handle(self):
        """
        Handle multiple requests - each expected to be a 4-byte length,
        followed by the LogRecord in pickle format. Logs the record
        according to whatever policy is configured locally.
        """
        self.connection.settimeout(1)
        while True:
            try:
                chunk = self.connection.recv(4)
            except socket.timeout:
                break
            if len(chunk) < 4:
                break
            slen = struct.unpack(">L", chunk)[0]
            chunk = self.connection.recv(slen)
            while len(chunk) < slen:
                chunk = chunk + self.connection.recv(slen - len(chunk))
            obj = LogRecordStreamHandler.un_pickle(chunk)
            record = logging.makeLogRecord(obj)
            self.handle_log_record(record)

    @staticmethod
    def un_pickle(data):
        """
        Unpickles data and returns it
        :param data: chunk of data
        :return: un_pickled object
        """
        return pickle.loads(data)

    def handle_log_record(self, record):
        """
        Every record gets logged.

        This is because Logger.handle is normally called after logger-level filtering.
        If you want to do filtering, do it at the client end to save wasting
        cycles and network bandwidth.

        :param record:
        :return:
        """
        # if a name is specified, we use the named logger rather than the one implied by the record.
        if self.server.logname is not None:
            name = self.server.logname
        else:
            name = record.name
        logger = logging.getLogger(name)
        logger.handle(record)
        if record.msg == LC_LOG_SERVER_ABORT:
            global SERVER_CONTINUE
            SERVER_CONTINUE = False
            self.connection.close()


class LogRecordSocketReceiver(socketserver.ThreadingTCPServer):
    """Simple TCP socket-based logging receiver suitable for testing."""

    allow_reuse_address = True

    def __init__(self, host=SERVER_HOST, port=LOGGER_PORT, handler=LogRecordStreamHandler):
        # type: (str, int, logging.Handler) -> None
        """
        Simple initialization of TCP LogRecord server.

        :param host: IP address of logger host
        :param port: port of logger host
        :param handler: log handler
        """
        socketserver.ThreadingTCPServer.__init__(self, (host, port), handler)
        self.timeout = 1
        self.logname = None

    def serve_until_stopped(self):
        """
        Starts the server and servers until aborted.
        :return: None
        """
        global SERVER_CONTINUE
        while SERVER_CONTINUE:
            rd, _, _ = select.select([self.socket.fileno()], [], [], self.timeout)
            if rd:
                self.handle_request()


def create_file_handlers(logs_file_path, *log_levels):
    # type: (str, *str) -> list
    """
    Create file handlers for provided log levels
    :param logs_file_path: path where logs should be stored
    :param log_levels: List of different log levels for which handlers should be created
    :return: list of created logging file handlers
    """
    file_handlers = []
    for log_level in log_levels:
        file_handler = logging.FileHandler(
            os.path.join(logs_file_path, "{}_ta_logcollector.log".format(log_level)), mode="a"
        )
        file_handler.setFormatter(logging.Formatter(fmt=LOG_FORMAT))
        file_handler.setLevel(getattr(logging, log_level))
        file_handlers.append(file_handler)
    return file_handlers


def run_log_server(directory, log_level):
    # type: (str, str) -> None
    """
    Entry point of starting TCP logging server.
    Launches receiver TCP server for LogCollector internal logs'
    :param directory: directory where internal logs should be stored')
    :param log_level: log level for console one of: CRITICAL, ERROR, WARNING, INFO, DEBUG'
    """
    logging.basicConfig(format=LOG_FORMAT)
    file_handlers = create_file_handlers(directory, "DEBUG", "INFO", "ERROR")
    root_logger = setup_root_logger(log_level)
    for file_handler in file_handlers:
        root_logger.addHandler(file_handler)
    tcpserver = LogRecordSocketReceiver()
    tcpserver.serve_until_stopped()


def setup_root_logger(log_level):
    # type: (str) -> logging.Logger
    """
    Configure and setup Root Logger.
    Set logging level base on LC_CONSOLE_LOG_LVL environment
    variable / CLI argument log_level, by default WARNING level is set.

    :param log_level: Console log level from cli argument or from LC_CONSOLE_LOG_LVL
    :return: root logger
    """
    root_log = logging.getLogger("")
    try:
        root_log.handlers[0].setLevel(getattr(logging, log_level.upper()))
    except Exception as exp:
        root_log.handlers[0].setLevel(logging.WARNING)
        root_log.exception("Error: {} during logger setup".format(exp))
    return root_log


def logsvr_args():
    # type: () -> argparse.Namespace
    """
    Parses provided arguments and returns dict with them
    :return: parsed arguments
    """
    parser = argparse.ArgumentParser(description="Launches receiver TCP server for logcollector internal logs")
    parser.add_argument(
        "-d", "--directory", required=True, type=str, help="directory where internal logs should be stored"
    )
    parser.add_argument("-v", "--version", required=True, type=str, help="logcollector version")
    parser.add_argument(
        "-l",
        "--log_level",
        required=True,
        type=str,
        help="log level for console one of: CRITICAL, ERROR, WARNING, INFO, DEBUG",
    )
    args = parser.parse_args()
    return args
